  const seedFiles = [{id:"KS-26091",debtor:"Hacer Karataş",customerNo:"31958370938",court:"İstanbul 9. İcra Dairesi",fileNo:"2025/26669",address:"Çiçekli Mah. 1234. Sk. No:18 Çankaya / Ankara",district:"Çankaya",vehicle:"06 AKH 286",risk:84500,status:"Havuz",assignee:"",payment:null,evidence:[]},{id:"KS-26092",debtor:"Beyhan Akdağ",customerNo:"12887031640",court:"İstanbul 1. İcra Dairesi",fileNo:"2025/26739",address:"Atatürk Bulvarı No:145 Çankaya / Ankara",district:"Çankaya",vehicle:"34 BA 7901",risk:124000,status:"Havuz",assignee:"",payment:null,evidence:[]}];
  const HEADERS=["Atama Ayı","Servis/Föy No","Müşteri No","Borçlu Adı","İcra Dairesi","İcra Dosya No","Açık Risk","Adres"];
  const $=s=>document.querySelector(s), esc=v=>String(v??"").replace(/[&<>\"]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[m])), loginKey=value=>String(value||"").trim().toLocaleLowerCase("tr-TR").replace(/[çÇ]/g,"c").replace(/[ğĞ]/g,"g").replace(/[ıİ]/g,"i").replace(/[öÖ]/g,"o").replace(/[şŞ]/g,"s").replace(/[üÜ]/g,"u");
  const supabaseUrl="https://gvxppmbbnhoxgfwsffko.supabase.co",supabaseKey="sb_publishable_-yUr9bAw4nUYQx7xB8Tlkw_gPyknLmB",cloud=window.supabase?.createClient?.(supabaseUrl,supabaseKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}}),isUuid=value=>/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value||""));
  const saved=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};
  const seedUsers=[{id:"admin",name:"Yönetici",username:"yonetici",password:"1234",role:"manager"},{id:"user-p1",name:"Çiğdem Şaşmaz",username:"cigdem",password:"1234",role:"field",employeeId:"p1"},{id:"user-p2",name:"Selda Bal",username:"selda",password:"1234",role:"field",employeeId:"p2"}];
  const storedUsers=saved("kesif-web-users",seedUsers);
  const state={page:"dashboard",role:"manager",files:saved("kesif-web-files",seedFiles),team:saved("kesif-web-team",seedTeam),users:Array.isArray(storedUsers)&&storedUsers.length?storedUsers:seedUsers,user:saved("kesif-web-session",null),selected:[],taskId:null,location:null,locationMessage:"Konum paylaşımı kapalı",watch:null};
  if(state.user&&!state.users.some(user=>user.id===state.user.id))state.user=null;
  // Eski cihazlardaki demo/yerel oturum hiçbir zaman canlı verinin yerine geçmesin.
  if(state.user&&!state.user.cloud){state.user=null;localStorage.removeItem("kesif-web-session")}
  let cloudSyncTimer=null,cloudSyncBusy=false;
  const save=(sync=true)=>{localStorage.setItem("kesif-web-files",JSON.stringify(state.files));localStorage.setItem("kesif-web-team",JSON.stringify(state.team));localStorage.setItem("kesif-web-users",JSON.stringify(state.users));localStorage.setItem("kesif-web-session",JSON.stringify(state.user));if(sync&&state.user?.cloud){clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(syncCloudState,350)}};
  const cloudTask=file=>({debtor_name:file.debtor,customer_no:file.customerNo||null,court_name:file.court||null,file_no:file.fileNo||null,address:file.address||"Adres belirtilmedi",district:file.district||null,vehicle_plate:file.vehicle||null,risk_amount:Number(file.risk)||0,status:file.status||"Havuz",assigned_to:isUuid(file.assignee)?file.assignee:null,assignment_month:file.assignmentMonth||null,service_no:file.serviceNo||null,phone:file.phone||null,created_by:state.user?.id||null});
  const localTask=row=>{let result=Array.isArray(row.discovery_results)?row.discovery_results[0]:row.discovery_results;return {id:row.id,debtor:row.debtor_name||"",customerNo:row.customer_no||"",court:row.court_name||"",fileNo:row.file_no||"",address:row.address||"",district:row.district||"",vehicle:row.vehicle_plate||"",risk:Number(row.risk_amount)||0,status:row.status||"Havuz",assignee:row.assigned_to||"",assignmentMonth:row.assignment_month||"",serviceNo:row.service_no||"",phone:row.phone||"",payment:result?.payment_received??null,paymentAmount:Number(result?.payment_amount)||0,addressConfirmed:result?.address_confirmed,contactMade:result?.contact_made||"",paymentIntent:result?.payment_intent||"",promiseDate:result?.payment_promise_date||"",vehiclePresent:result?.vehicle_present,vehicleState:result?.vehicle_state||"",fieldNote:result?.field_note||"",outcome:result?.contact_outcome||"",completedAt:result?.completed_at||null,evidence:[]}};
  async function loadCloudData(){if(!cloud||!state.user?.cloud)return;let {data,error}=await cloud.from("discovery_tasks").select("*,discovery_results(*),discovery_media(*) ").order("created_at",{ascending:false});if(error)throw error;state.files=await Promise.all((data||[]).map(async row=>{let file=localTask(row),media=row.discovery_media||[];file.evidence=await Promise.all(media.map(async item=>{let {data}=await cloud.storage.from("discovery-media").createSignedUrl(item.storage_path,3600);return {name:item.file_name,url:data?.signedUrl||""}}));return file}));if(state.role==="manager"){let people=await cloud.from("discovery_accounts").select("id,display_name,username,role,active").eq("active",true).order("display_name");if(!people.error)state.team=(people.data||[]).map((x,i)=>({id:x.id,name:x.display_name||x.username,initials:(x.display_name||x.username).split(" ").map(part=>part[0]).join("").slice(0,2).toUpperCase(),color:["violet","teal","amber"][i%3],online:false,location:"Konum bekleniyor"}))}save(false)}
  async function createCloudTasks(files){if(!cloud||!state.user?.cloud||!files.length)return;let {error}=await cloud.from("discovery_tasks").insert(files.map(cloudTask));if(error)throw error;await loadCloudData()}
  async function updateCloudTask(file){if(!cloud||!state.user?.cloud||!isUuid(file.id))return;let {error}=await cloud.from("discovery_tasks").update(cloudTask(file)).eq("id",file.id);if(error)throw error}
  async function deleteCloudTasks(ids){if(!cloud||!state.user?.cloud||!ids.every(isUuid))return;let {error}=await cloud.from("discovery_tasks").delete().in("id",ids);if(error)throw error}
  async function saveCloudResult(file){if(!cloud||!state.user?.cloud||!isUuid(file.id))return;await updateCloudTask(file);let payload={task_id:file.id,address_confirmed:file.addressConfirmed??null,contact_made:file.contactMade||null,contact_outcome:file.outcome||null,payment_intent:file.paymentIntent||null,payment_received:file.payment??null,payment_amount:Number(file.paymentAmount)||0,payment_promise_date:file.promiseDate||null,vehicle_present:file.vehiclePresent??null,vehicle_state:file.vehicleState||null,field_note:file.fieldNote||null,completed_by:state.user.id,completed_at:file.completedAt||new Date().toISOString()};let {error}=await cloud.from("discovery_results").upsert(payload,{onConflict:"task_id"});if(error)throw error}
  async function syncCloudState(){if(!cloud||!state.user?.cloud||cloudSyncBusy)return;cloudSyncBusy=true;try{let fresh=state.files.filter(file=>!isUuid(file.id)),existing=state.files.filter(file=>isUuid(file.id));for(let file of existing){await updateCloudTask(file);if(file.status==="Tamamlandı"||file.completedAt)await saveCloudResult(file)}if(fresh.length)await createCloudTasks(fresh);await loadCloudData();render()}catch(error){console.warn("Canlı eşitleme başarısız",error)}finally{cloudSyncBusy=false}}
  let liveChannel=null;
  function subscribeCloud(){if(!cloud||!state.user?.cloud||liveChannel)return;liveChannel=cloud.channel("discovery-live").on("postgres_changes",{event:"*",schema:"public",table:"discovery_tasks"},async()=>{if(!cloudSyncBusy){await loadCloudData();render()}}).on("postgres_changes",{event:"*",schema:"public",table:"discovery_results"},async()=>{if(!cloudSyncBusy){await loadCloudData();render()}}).subscribe()}
