  const person=id=>state.team.find(p=>p.id===id);
  const setPage=p=>{state.page=p;render()};
  function layout(content){const pool=state.files.filter(f=>f.status==="Havuz").length,act=active().length,userName=state.user?.name||state.user?.username||"Keşif kullanıcısı",initials=userName.split(" ").map(part=>part[0]).join("").slice(0,2).toUpperCase();return `<div class="app"><aside class="sidebar"><div class="brand"><div class="brand-mark"><span>K</span></div><div><b>Keşif Paneli</b><small>Saha operasyon merkezi</small></div></div><div class="mode"><button class="${state.role==="manager"?"on":""}" data-role="manager">Yönetici</button><button class="${state.role==="field"?"on":""}" data-role="field">Personel</button></div><p class="menu-title">OPERASYON</p><nav class="nav">${[["dashboard","▦","Genel Bakış"],["files","▤","Dosya Havuzu",pool],["tasks","✓","Keşif Görevleri"],["map","⌖","Canlı Konum"],["results","▣","Keşif Sonuçları"],["reports","↓","Raporlar"],["team","♙","Personeller"]].filter(x=>state.role==="manager"||!["files","team"].includes(x[0])).map(x=>`<button data-page="${x[0]}" class="${state.page===x[0]?"on":""}"><span class="nav-icon">${x[1]}</span><span class="nav-label">${x[2]}</span>${x[3]!==undefined?`<em>${x[3]}</em>`:""}</button>`).join("")}</nav><div class="me"><i class="avatar">${initials}</i><div><b>${esc(userName)}</b><small>${state.role==="manager"?"Yönetici":"Keşif personeli"}</small></div><div class="account-actions"><button class="logout" id="changePassword" title="Şifre değiştir">Şifre</button><button class="logout" id="logout" title="Çıkış yap">Çıkış</button></div></div></aside><main class="main"><header class="top"><div><p class="eyebrow">SAHA OPERASYONLARI</p><h1>${({dashboard:"Keşif Merkezi",files:"Dosya Havuzu",tasks:"Keşif Görevleri",map:"Canlı Konum",results:"Keşif Sonuçları",reports:"Rapor Merkezi",team:"Saha Personelleri"}[state.page])}</h1></div><div><button class="btn" id="share">⌖ Konumumu paylaş</button></div></header>${content}</main></div>`}
  const stats=()=>{const done=state.files.filter(f=>f.status==="Tamamlandı").length,paid=state.files.filter(f=>f.payment).length;return [["▤",state.files.filter(f=>f.status==="Havuz").length,"Havuzdaki dosya"],["✓",active().length,"Aktif keşif"],["▣",done,"Tamamlanan"],["◉",paid,"Ödeme alınan"]]};
  function dashboard(){return layout(`<section class="cards">${stats().map(x=>`<article class="card"><i>${x[0]}</i><div><b>${x[1]}</b><span>${x[2]}</span></div></article>`).join("")}</section><section class="grid2"><article class="panel"><div class="head"><div><p class="eyebrow">OPERASYON AKIŞI</p><h2>Dosyadan sonuca</h2></div><button class="btn" data-page="files">Dosya havuzunu aç</button></div><div class="workflow"><div><b>1</b><strong>Şablonu yükle</strong><span>Dosyalar önce havuza iner.</span></div><div><b>2</b><strong>Toplu ata</strong><span>Seçilenler görev olur.</span></div><div><b>3</b><strong>Sonucu izle</strong><span>Görsel ve ödeme yönetime gelir.</span></div></div></article><article class="panel"><div class="head"><div><p class="eyebrow">SAHA EKİBİ</p><h2>Canlı durum</h2></div></div><div class="live">${teamRows()}</div></article></section><section class="panel" style="margin-top:16px"><div class="head"><div><p class="eyebrow">SON DOSYALAR</p><h2>Bekleyen işler</h2></div></div>${table(state.files.slice(0,6),false)}</section>`)}
