  function table(files,checks){return `<div class="table-wrap"><table><thead><tr>${checks?"<th></th>":""}<th>Borçlu / Dosya</th><th>Adres</th><th>İcra dairesi</th><th>Plaka</th><th>Risk</th><th>Durum</th></tr></thead><tbody>${files.map(f=>`<tr>${checks?`<td><input class="pick" data-id="${f.id}" type="checkbox" ${state.selected.includes(f.id)?"checked":""}></td>`:""}<td><b>${esc(f.debtor)}</b><small>${esc(f.fileNo)} · ${esc(f.customerNo)}</small></td><td>${esc(f.address)}</td><td>${esc(f.court)}</td><td>${esc(f.vehicle||"-")}</td><td><b>${money(f.risk)}</b></td><td><span class="status ${tone(f.status)}">${f.status}</span></td></tr>`).join("")||`<tr><td colspan="7">Kayıt bulunmuyor.</td></tr>`}</tbody></table></div>`}
  function files(){let query=state.fileQuery||"",sort=state.fileSort||"name";let rows=state.files.filter(f=>f.status==="Havuz").filter(f=>`${f.debtor} ${f.address} ${f.fileNo} ${f.customerNo} ${f.risk}`.toLocaleLowerCase("tr-TR").includes(query.toLocaleLowerCase("tr-TR")));rows.sort((a,b)=>sort==="risk"?b.risk-a.risk:sort==="address"?a.address.localeCompare(b.address,"tr"):a.debtor.localeCompare(b.debtor,"tr"));return layout(`<section class="panel"><div class="head"><div><p class="eyebrow">DOSYA HAVUZU</p><h2>Atama bekleyen dosyalar</h2><p>Yüklenen Excel önce buraya gelir; seçmeden hiçbir dosya görev listesine geçmez.</p></div><label class="btn primary">⇧ Şablon yükle<input class="hidden" id="import" type="file" accept=".xlsx,.xls"></label></div><div class="tools"><label class="search">⌕<input id="q" value="${esc(query)}" placeholder="İsim, adres, dosya no veya miktar ara"></label><select id="sort"><option value="name">İsme göre</option><option value="address">Adrese göre</option><option value="risk">Risk tutarına göre</option></select><select id="assign"><option value="">Personel seçin</option>${state.team.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join("")}</select><button class="btn primary" id="assignGo" ${state.selected.length?"":"disabled"}>♙ Seçilenleri ata</button><button class="btn danger" id="delete" ${state.selected.length?"":"disabled"}>⌫ Sil</button><label class="btn">↓ Tahsilat uygula<input class="hidden" id="collection" type="file" accept=".xlsx,.xls"></label></div><div class="select-bar"><label><input id="all" type="checkbox" ${rows.length&&state.selected.length===rows.length?"checked":""}> Tümü (${rows.length})</label><span>${state.selected.length} dosya seçildi</span></div>${table(rows,true)}</section>`)}
  function tasks(){let rows=(state.role==="field"?active().filter(f=>f.assignee===state.user?.employeeId):active()),t=task();return layout(`<section class="task-layout"><article class="panel task-list"><div class="tools"><label class="search">⌕<input id="taskSearch" placeholder="Görev veya adres ara"></label></div><div class="select-bar"><span>${rows.length} aktif görev</span></div>${rows.map(f=>`<button class="task-row ${t?.id===f.id?"active":""}" data-task="${f.id}"><i class="dot"></i><div><b>${esc(f.debtor)}</b><small>${esc(f.fileNo)} · ${esc(f.district)}</small><em>${esc(f.address)}</em></div><span class="status ${tone(f.status)}">${f.status}</span></button>`).join("")||"<p style='padding:20px'>Aktif görev yok.</p>"}</article>${detail(t)}</section>`)}
  function detail(f){if(!f)return `<aside class="panel detail"><p>Bir görev seçin.</p></aside>`;let p=person(f.assignee);return `<aside class="panel detail"><div class="detail-top"><div><p class="eyebrow">${f.id}</p><h2>${esc(f.debtor)}</h2><p>${esc(f.court)} · ${esc(f.fileNo)}</p></div><span class="status ${tone(f.status)}">${f.status}</span></div><section class="address"><i>⌖</i><div><p class="eyebrow">GÖREV ADRESİ</p><strong>${esc(f.address)}</strong><small>${esc(f.phone||"Telefon bilgisi yok")}</small></div><button data-map="${encodeURIComponent(f.address)}">➜</button></section><div class="data-grid"><div><span>AÇIK RİSK</span><b>${money(f.risk)}</b></div><div><span>PLAKA</span><b>${esc(f.vehicle||"Kayıt yok")}</b></div><div><span>ATANAN</span><b>${esc(p?.name||"Atanmadı")}</b></div><div><span>GÖRSEL</span><b>${f.evidence?.length||0} dosya</b></div></div>${state.role==="manager"?`<section class="assign"><span>PERSONEL ATA</span><div>${state.team.map(x=>`<button class="person ${f.assignee===x.id?"active":""}" data-quickassign="${x.id}" data-id="${f.id}"><i class="avatar ${x.color}">${x.initials}</i>${esc(x.name.split(" ")[0])}</button>`).join("")}</div></section>`:""}<section class="summary"><span class="result-title">CANLI SONUÇ</span><div><b>Adres teyidi</b><em>${f.addressConfirmed===undefined?"Bekliyor":f.addressConfirmed?"Evet":"Hayır"}</em></div><div><b>Ödeme</b><em>${f.payment===null?"Bekliyor":f.payment?"Alındı":"Alınmadı"}</em></div></section>${state.role==="field"?`<button class="btn primary full" id="result">✓ Keşif sonucunu gir</button>`:""}</aside>`}
  function map(){return layout(`<section class="grid2"><article class="panel map"><i class="road a"></i><i class="road b"></i>${state.files.slice(0,3).map((f,i)=>`<div class="pin ${["a","b","c"][i]}">⌖<span>${esc(f.debtor)}</span></div>`).join("")}${state.location?"<div class='mepin'>⌖ Benim konumum</div>":""}<div class="mapinfo"><b>Canlı konum</b><span>${esc(state.locationMessage)}</span><button class="btn" id="checkLocation">Konum iznini kontrol et</button></div></article><aside class="panel"><div class="head"><div><p class="eyebrow">SAHA EKİBİ</p><h2>Canlı personel durumu</h2></div></div><div class="live">${teamRows()}</div></aside></section>`)}
  function results(){let rows=state.files.filter(f=>f.status==="Tamamlandı");return layout(`<section class="panel"><div class="head"><div><p class="eyebrow">KEŞİF SONUÇLARI</p><h2>Tamamlanan görevler ve kanıtlar</h2></div></div><div class="table-wrap"><table><thead><tr><th>Dosya</th><th>Personel</th><th>Ödeme</th><th>Araç</th><th>Görseller</th></tr></thead><tbody>${rows.map(f=>`<tr><td><b>${esc(f.debtor)}</b><small>${esc(f.fileNo)}</small></td><td>${esc(person(f.assignee)?.name||"-")}</td><td>${f.payment?`${money(f.paymentAmount)} alındı`:"Ödeme alınmadı"}</td><td>${f.vehiclePresent?"Araç tespit edildi":"Tespit yok"}</td><td><div class="images">${f.evidence?.length?f.evidence.map(m=>`<a href="${m.url}" target="_blank"><img src="${m.url}" alt="${esc(m.name)}"></a>`).join(""):"Görsel yok"}</div></td></tr>`).join("")||"<tr><td colspan='5'>Tamamlanan görev yok.</td></tr>"}</tbody></table></div></section>`)}
