  async function importFiles(e){let file=e.target.files[0];if(!file)return;try{let book=XLSX.read(await file.arrayBuffer(),{type:"array"}),rows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:""}),missing=HEADERS.filter(h=>!Object.keys(rows[0]||{}).includes(h));if(missing.length)throw Error(`Şablon uygun değil. Eksik sütun: ${missing.join(", ")}`);let text=(r,k)=>String(r[k]||"").trim(),amount=v=>Number(String(v||"").replace(/[^0-9,.-]/g,"").replace(/\.(?=.*\.)/g,"").replace(",","."))||0,added=rows.map((r,i)=>({id:`KS-${String(Date.now()).slice(-6)}-${i+1}`,assignmentMonth:text(r,"Atama Ayı"),serviceNo:text(r,"Servis/Föy No"),customerNo:text(r,"Müşteri No"),debtor:text(r,"Borçlu Adı"),debtorType:text(r,"Borçlu Türü"),court:text(r,"İcra Dairesi"),fileNo:text(r,"İcra Dosya No"),risk:amount(r["Açık Risk"]),phone:text(r,"Telefonlar"),criterion:text(r,"Kriter"),vehicle:text(r,"Plakalar"),address:text(r,"Adres"),district:text(r,"Adres").split("/").slice(-2,-1)[0]?.replace(/^\d+\s*/,"")||"Belirsiz",status:"Havuz",assignee:"",payment:null,evidence:[]})).filter(x=>x.debtor||x.address);if(!added.length)throw Error("Dosyada kullanılabilir satır bulunamadı.");state.files=[...added,...state.files];save();alert(`${added.length} dosya havuza eklendi. Görev listesine henüz düşmedi.`);render()}catch(err){alert(err.message||"Dosya okunamadı.")}}
  async function collection(e){let file=e.target.files[0];if(!file)return;try{let book=XLSX.read(await file.arrayBuffer(),{type:"array"}),rows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:""}),n=0;state.files=state.files.map(f=>{let r=rows.find(x=>String(x["Müşteri No"]||x["Musteri No"]||"")===f.customerNo||String(x["İcra Dosya No"]||x["Dosya No"]||"")===f.fileNo),k=r&&Object.keys(r).find(x=>/tahsilat|ödeme|odeme/i.test(x)),paid=Number(String(r?.[k]||"").replace(/[^0-9,.-]/g,"").replace(/\.(?=.*\.)/g,"").replace(",","."))||0;if(!paid)return f;n++;let risk=Math.max(0,f.risk-paid);return {...f,risk,payment:true,paymentAmount:(Number(f.paymentAmount)||0)+paid,status:risk<1000?"İnfaz":f.status}});save();alert(`${n} dosya işlendi. 1.000 TL altı bakiye infaza alındı.`);render()}catch(err){alert(err.message||"Tahsilat raporu okunamadı.")}}
  function assignSelected(){let id=$("#assign")?.value;if(!id||!state.selected.length)return;state.files=state.files.map(f=>state.selected.includes(f.id)?{...f,assignee:id,status:"Atandı"}:f);state.selected=[];save();state.page="tasks";render()}
