  function exportReport(period){let ms={daily:86400000,weekly:604800000,monthly:2678400000}[period],rows=state.files.filter(f=>!f.completedAt||Date.now()-new Date(f.completedAt)<ms).map(f=>({"Atama Ayı":f.assignmentMonth||"","Servis/Föy No":f.serviceNo||"","Müşteri No":f.customerNo,"Borçlu Adı":f.debtor,"İcra Dairesi":f.court,"İcra Dosya No":f.fileNo,"Açık Risk":f.risk,Adres:f.address,Durum:f.status,"Ödeme alındı":f.payment?"Evet":"Hayır","Ödeme tutarı":f.paymentAmount||0,"Görsel sayısı":f.evidence?.length||0})),book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(rows),"Keşif Raporu");XLSX.writeFile(book,`kesif-${period}-${new Date().toISOString().slice(0,10)}.xlsx`)}
  function personModal(){document.body.insertAdjacentHTML("beforeend",`<div class="modalbg" id="modal"><form class="modal" style="max-width:500px" id="personForm"><div class="modal-head"><div><p class="eyebrow">YENİ PERSONEL</p><h2>Keşif personeli ekle</h2></div><button class="close" type="button" id="close">×</button></div><div style="padding:24px"><label class="field">Ad soyad<input required name="name" autofocus placeholder="Personelin adı soyadı"></label><label class="field">Kullanıcı adı<input required name="username" autocomplete="off" placeholder="Örn. ayse.demir"></label><label class="field">Geçici şifre<input required name="password" type="password" autocomplete="new-password" minlength="4" placeholder="En az 4 karakter"></label><label class="field">Renk<select name="color"><option value="violet">Mor</option><option value="teal">Turkuaz</option><option value="amber">Turuncu</option></select></label></div><div class="modal-foot"><button class="btn primary">＋ Personeli ekle</button></div></form></div>`);let m=$("#modal");$("#close").onclick=()=>m.remove();$("#personForm").onsubmit=e=>{e.preventDefault();let data=new FormData(e.target),name=String(data.get("name")).trim(),username=String(data.get("username")).trim().toLocaleLowerCase("tr-TR");if(state.users.some(x=>x.username.toLocaleLowerCase("tr-TR")===username))return alert("Bu kullanıcı adı zaten kullanılıyor.");let id=`p-${Date.now()}`;state.team.push({id,name,initials:name.split(" ").map(x=>x[0]).join("").slice(0,2).toUpperCase(),color:data.get("color"),online:false,location:"Konum bekleniyor"});state.users.push({id:`user-${Date.now()}`,name,username,password:String(data.get("password")),role:"field",employeeId:id});save();m.remove();render()}}
