  function passwordModal(){document.body.insertAdjacentHTML("beforeend",`<div class="modalbg" id="passwordModal"><form class="modal" style="max-width:460px" id="passwordForm"><div class="modal-head"><div><p class="eyebrow">HESAP GÜVENLİĞİ</p><h2>Şifre değiştir</h2><p>${esc(state.user.name)} hesabı</p></div><button class="close" type="button" id="closePassword">×</button></div><div style="padding:24px"><label class="field">Mevcut şifre<input name="current" type="password" autocomplete="current-password" required></label><label class="field">Yeni şifre<input name="next" type="password" autocomplete="new-password" minlength="4" required></label><label class="field">Yeni şifre tekrar<input name="repeat" type="password" autocomplete="new-password" minlength="4" required></label><p class="login-error" id="passwordError"></p></div><div class="modal-foot"><button type="button" class="btn" id="cancelPassword">Vazgeç</button><button class="btn primary">Şifreyi güncelle</button></div></form></div>`);let modal=$("#passwordModal"),form=$("#passwordForm"),close=()=>modal.remove();$("#closePassword").onclick=close;$("#cancelPassword").onclick=close;form.onsubmit=e=>{e.preventDefault();let data=new FormData(form),current=String(data.get("current")),next=String(data.get("next")),repeat=String(data.get("repeat"));if(current!==state.user.password)return $("#passwordError").textContent="Mevcut şifre doğru değil.";if(next!==repeat)return $("#passwordError").textContent="Yeni şifreler eşleşmiyor.";state.users=state.users.map(user=>user.id===state.user.id?{...user,password:next}:user);state.user=state.users.find(user=>user.id===state.user.id);save();close();alert("Şifreniz güncellendi.")}}
  function registerModal(){document.body.insertAdjacentHTML("beforeend",`<div class="modalbg" id="registerModal"><form class="modal" style="max-width:460px" id="registerForm"><div class="modal-head"><div><p class="eyebrow">BAĞIMSIZ KEŞİF HESABI</p><h2>İlk yönetici hesabını oluştur</h2><p>Bu hesap Call Center kullanıcılarından tamamen ayrıdır.</p></div><button class="close" type="button" id="closeRegister">×</button></div><div style="padding:24px"><label class="field">Ad soyad<input name="name" required autofocus placeholder="Örn. Melih Volkan Canalp"></label><label class="field">Kullanıcı adı<input name="username" required pattern="[a-zA-Z0-9._-]{3,}" placeholder="Örn. kesif.yonetici"></label><label class="field">Şifre<input name="password" type="password" required minlength="6" placeholder="En az 6 karakter"></label><p class="login-error" id="registerError"></p></div><div class="modal-foot"><button class="btn primary">Hesabı oluştur</button></div></form></div>`);let modal=$("#registerModal"),form=$("#registerForm");$("#closeRegister").onclick=()=>modal.remove();form.onsubmit=async e=>{e.preventDefault();let data=new FormData(form),username=loginKey(data.get("username")),password=String(data.get("password")),name=String(data.get("name")).trim();try{let {error}=await cloud.auth.signUp({email:`${username}@kesifpanel.app`,password,options:{data:{app:"kesif",username,display_name:name}}});if(error)throw error;modal.remove();alert("Keşif hesabı oluşturuldu. Şimdi aynı bilgilerle giriş yapabilirsiniz.")}catch(error){$("#registerError").textContent=error.message||"Hesap oluşturulamadı."}}}
